import fs from 'fs';
import path from 'path';

// All site data lives in /content (generated by tools/extract.mjs from the WordPress site).
const CONTENT = path.join(process.cwd(), 'content');

export type Attrs = Record<string, string>;
export type PageData = {
  path: string;
  status: number;
  type: 'page' | 'post' | 'archive' | 'error' | 'search';
  lang: string;
  title: string;
  metas: Attrs[];
  links: Attrs[];
  jsonld: string[];
  styles: string[];
  bodyClass: string;
  popupMeta: { refererTitle: string; queriedId: string; settings?: string };
  scripts: { code: string; id: string }[];
  html: string;
};
export type RouteInfo = { key: string; status: number; type: string; title: string };
export type Layout = { header: string; footer: string; popup: string };

const cache = new Map<string, unknown>();
function readJson<T>(file: string): T {
  if (!cache.has(file)) cache.set(file, JSON.parse(fs.readFileSync(path.join(CONTENT, file), 'utf8')));
  return cache.get(file) as T;
}

export const getRoutes = () => readJson<Record<string, RouteInfo>>('routes.json');
export const getLayout = () => readJson<Layout>('layout.json');
export const getCards = () => readJson<Record<string, string>>('cards.json');
export type SearchEntry = { path: string; type: string; title: string; seoTitle: string; description: string; text: string; image?: string; date?: string };
export const getSearchIndex = () => readJson<SearchEntry[]>('search-index.json');

export function getPage(routePath: string): PageData | null {
  const r = getRoutes()[routePath];
  if (!r) return null;
  // page files are read on demand and not cached (453 pages, ~34 MB)
  return JSON.parse(fs.readFileSync(path.join(CONTENT, 'pages', r.key + '.json'), 'utf8'));
}

export function getSpecialPage(key: '__404' | '__search'): PageData {
  return readJson<PageData>(`pages/${key}.json`);
}

/** Public site URL used in canonical / Open Graph / schema tags. */
export const SITE_URL = (process.env.SITE_URL || 'https://www.fixwebsiteissues.com').replace(/\/$/, '');
const LIVE = /https?:\/\/(?:www\.)?fixwebsiteissues\.com/g;
export const siteUrl = (s: string) => (SITE_URL === 'https://www.fixwebsiteissues.com' ? s : s.replace(LIVE, SITE_URL));
